INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f3e68973-28c5-4a37-ace7-e336d7795b86', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'RAID Builder', 'Create RAID0: mdadm --create /dev/md0 --level=0 --raid-devices=2 /tmp/disk1.img /tmp/disk2.img 2>/dev/null; Run: cat /proc/mdstat | grep md0 | awk "{print $4}". What is the status?', 100, '$2b$10$c0GBm2rhmEb4gSQ6gaDv8OA0RcgmksjwJKENPiNbUIxGbkrQ4a7iS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ef3e7082-7021-4e9d-88da-07b5e7f3603b', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Swap Creator', 'Create 50MB swap: dd if=/dev/zero of=/tmp/swap.img bs=1M count=50 && mkswap /tmp/swap.img && swapon /tmp/swap.img. Run: swapon --show | wc -l. How many swap devices (minus header)?', 100, '$2b$10$mzdfVXXcAwCg6t4HnoCM2eCRTzV6.V8GdoYgKAakcnkMl8kmiGPq2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bf1207de-7ae8-4a0a-9254-97ee630e0ae6', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'DF Detective', 'Run: df -h --output=source,size,used,avail,target | grep tmp | head -1. What is the mount point?', 75, '$2b$10$VASRGf/BKnZocCoxswLNqOzOHQjMpe8cHUmbpxTkckyvHyujv.dpi');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f53a6f81-dfad-4450-87cd-b19780beae2a', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fstab Editor', 'Add to /etc/fstab: /tmp/disk.img /mnt/data ext4 loop 0 0. Run: grep "/mnt/data" /etc/fstab | awk "{print $3}". What filesystem type is listed?', 100, '$2b$10$eZjp8ZKt8Qa/4mE6NzQ/Yety6pgQ696n1zdRnTcrm/4obH.XXPIQO');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('17c274fb-098d-4946-9045-f5402e9f0d99', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Inode Counter', 'Run: df -i / | tail -1 | awk "{print $4}". How many free inodes?', 100, '$2b$10$LVVMHs3GUpOnQ2hnayY98.nKuehaIKToylmeSPEncaGRWqUb3Mliq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0a02708c-3988-4f50-a5c4-137c0b6cb70f', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Du Analyzer', 'Create files in /mnt/data (dd if=/dev/zero of=/mnt/data/bigfile bs=1M count=10). Run: du -sh /mnt/data | awk "{print $1}". What is the size?', 100, '$2b$10$AePmwjkhGo39I/zBlzUo8u3HSOqi6ldQjG6DLeHUbng6fyCO0qbty');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6d0ed500-e51e-4dc3-85d7-dc738d738f5f', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'UUID Finder', 'Run: blkid /dev/loop0 2>/dev/null | grep -o "UUID=\"[^ ]*\"" | head -1. What is the UUID format? (just answer "uuid" if you can see it)', 75, '$2b$10$dHNtqbefgYBhCFlAM7W6R.nbNmeyN9dcvh75IL3n9KQ2yRd8Bbm1K');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8ebb4bac-f9b5-4010-b104-54e3c4f8eb2a', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fdisk Explorer', 'Run: fdisk -l /tmp/disk.img 2>/dev/null | head -5. What disk identifier type is shown?', 100, '$2b$10$IAmo2rZq6L7DlvLAI10SdunCcFnn2dbLlB6rEOlrQDtyTfKmXUEk2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0f795931-1be6-4f3d-8f86-7a60c8bc1436', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Cleanup Crew', 'Run: umount /mnt/data && losetup -D && vgremove -f myvg 2>/dev/null; echo "storage_done". What is the output?', 75, '$2b$10$Laj/hhiYqPZ4lxW9aovF7ek5RMFy9MsbsuA1EKlB6ieZYCGC7vT66');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8fa84483-866a-4c71-a360-892c9a19fc1c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Tar Crafter', 'Create /home/student/backup_data/ with 3 files (a.txt, b.txt, c.txt). Pack: tar czf /tmp/backup.tar.gz -C /home/student backup_data. Run: tar tzf /tmp/backup.tar.gz | wc -l. How many entries?', 75, '$2b$10$3deYoKB0l/SOUCpdZ7lNMeF14Obs1i0wTnwu6ePB4YnisRCmwTf8W');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d77f3294-3b52-435c-958e-5fbe76efd961', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Scheduler', 'Add cron job: echo "0 * * * * echo backup_ok > /tmp/cron_proof" | crontab -. Run: crontab -l | wc -l. How many cron entries?', 75, '$2b$10$wpCl.6K7qVSgnvzzRo0Uw./Tnb.q5qg8NxEDu2ApegQCT9SW9PqqK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('96d5fa6e-7fbe-45e7-84e1-289c13d5b6f8', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Restore Tester', 'Create /tmp/restore_dir/. Extract backup: tar xzf /tmp/backup.tar.gz -C /tmp/restore_dir. Run: ls /tmp/restore_dir/backup_data/ | wc -l. How many files restored?', 100, '$2b$10$XnWUKVXwUhS8/VzRLbeVTePEYWLuAqyyMaX.fJW4XhqdTzcxP2sta');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d73c4c3d-2f62-429d-b5b0-c28013250f10', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Incremental Creator', 'Create new file d.txt. Create incremental: tar czf /tmp/incr.tar.gz -C /home/student/backup_data --newer=a.txt . Run: tar tzf /tmp/incr.tar.gz. What file is listed?', 100, '$2b$10$rEr7sKkMi2kqyTa/jOHDVeLwktVjmMd2Z1LDefKULrZqFPsm4qZ8e');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('52f68e40-6d98-4f6f-b15d-41865c472ef0', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'rsync Master', 'Create /tmp/src_dir/ and /tmp/dst_dir/. Create file in src. Run: rsync -av /tmp/src_dir/ /tmp/dst_dir/ && ls /tmp/dst_dir/. What file is synced?', 100, '$2b$10$j6ftDJNlr/qHW7T6UOYdI.0Y5.TMJ3jDiZt.rLVa22x4cv817Io3K');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('13ea3a65-f733-40b6-bdba-9115d8e91a0d', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Exclusion Expert', 'Create files: log.txt, data.csv, log2.txt. Run: tar czf /tmp/no_logs.tar.gz --exclude="log*" -C /home/student/backup_data . Run: tar tzf /tmp/no_logs.tar.gz | grep -c log. How many log files included?', 100, '$2b$10$pPvCZZmzmw2Cy7RuDAlVFubCVkHfFs59w3uhxVqmAUI6HHEEPaGXy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ede8c02d-b7d6-41a3-875d-0656913c196e', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Compression Pro', 'Compare: tar czf /tmp/gz.tar.gz -C /home/student/backup_data . vs tar cJf /tmp/xz.tar.xz -C /home/student/backup_data . Run: ls -la /tmp/gz.tar.gz /tmp/xz.tar.xz | awk "{print $5, $9}". Which is smaller?', 100, '$2b$10$mWc7QF4n7AYZIRHNhmIvXehTq7.zatkybwwjSZ.bIhAce97q4DHHK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('446b007e-e985-49d6-a7a2-6850b20ab77e', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Verify Expert', 'Run: tar tzf /tmp/backup.tar.gz > /tmp/list.txt && md5sum /tmp/list.txt. What is the first 8 chars of the hash?', 100, '$2b$10$XsbkB/oi.Mf684UVBiE7xenEtYWklf7ZByptsFqrX95wMOIf1ah/2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('edbc517e-24e7-4efa-94f1-0f8a880f57d3', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Docker Backup', 'Run: docker run -d --name db-backup alpine:3.18 sleep 300. Then: docker export db-backup > /tmp/container_backup.tar && wc -c /tmp/container_backup.tar. How many bytes (approximately)?', 100, '$2b$10$Gf2rjeaTZgUrdZ3YklP49OXna0YQzpImFd6SL6nPoLxi7uFNnapY6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f9f09fd2-f3cf-4660-851a-cc60df0c2651', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Checker', 'Run: cat /var/spool/cron/crontabs/root 2>/dev/null | head -1. What is the cron schedule?', 75, '$2b$10$t7kh3R6wf5Mu/mab8v6aBuaMBfcM37GUCLrYMsHR.Nq3huvfVRKgS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('39ade2bc-6d03-4748-b8a8-c5e9380d744c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Diff Backup', 'Create /tmp/original/file.txt with "old". Copy to /tmp/backup_version/. Change original to "new". Run: diff /tmp/original/file.txt /tmp/backup_version/file.txt. What is shown?', 100, '$2b$10$zq.okqm1zNyEPthIswNDe.CeY23Cq3CIchfP3XnqwVSQ9yFLsk0kC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9ce602d5-3073-40f1-98c0-c16ad38c2442', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Archive Inspector', 'Run: file /tmp/backup.tar.gz. What is the detected type?', 75, '$2b$10$h.sFqveLlGQwoSesxb9TZOQ/PQ1VgkfD8fdGQ/WgssjkW6ZDibaS2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('19863eb2-96e8-4473-ae4b-6b24776f28a6', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cleanup Script', 'Create /home/student/cleanup.sh that removes /tmp/restore_dir, /tmp/incr.tar.gz, /tmp/gz.tar.gz, /tmp/xz.tar.xz and echoes "cleaned". chmod +x and run. What is the output?', 100, '$2b$10$TyxX/Ic/I5YPro4EbBeb4eUmHz7uEm4qwdszGW3aUAo4CyXNbktha');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3c50a7bd-7479-48ee-9c5d-cef679afb305', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Checksum Verifier', 'Run: sha256sum /tmp/backup.tar.gz | awk "{print $1}" | wc -c. How many characters is the SHA256 hash?', 75, '$2b$10$9fYnJ9r8b7sF6uSD9plx1.ltCjhh7UQ9OcMQl4gI5lfi2822QKNli');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f7260a1b-3f2c-4dbf-945c-f339b7431abe', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Date Stamped Backup', 'Run: tar czf /tmp/backup_$(date +%Y%m%d).tar.gz -C /home/student/backup_data . && ls /tmp/backup_*.tar.gz | wc -l. How many date-stamped backups?', 100, '$2b$10$VvWS./ieMPhzEe4cMUoY7.4pBSu6JLiBuELQa0U5fgsnW3AopeklK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8a90d97a-6eca-45d3-84fe-34116fdbc95f', '884ee166-21d8-4336-a519-6ccdf111068c', 'iptables List', 'Run: iptables -L -n | head -3. What is the first chain name shown?', 50, '$2b$10$VEMsrqEuH3HhSazdPrBpOuEKvZGDeLq6tbBRDf73/Kn1rOxqrtiKi');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('12f57cb9-f62a-4147-bc4a-6b87d5d8841a', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Creator', 'Run: iptables -A INPUT -p tcp --dport 8080 -j ACCEPT && iptables -L INPUT -n | grep 8080. What target is shown?', 75, '$2b$10$bBEbC7lBjKSFAwuLehRb1OTX/sEC5XgJnnohfy1Mid7o7Y4/eTFQC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4e3f4f11-d825-4d78-9962-db147cd4a14f', '884ee166-21d8-4336-a519-6ccdf111068c', 'Port Blocker', 'Run: iptables -A INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep 9999. What target?', 75, '$2b$10$/PJXrKLi6w9v5gz3qDB4rOk1HiPyDAl6EwhHZfwrtpwESc2vox8w2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f018ecae-d1e7-4314-9452-2801185e083f', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Deleter', 'Run: iptables -D INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep -c 9999. How many rules for port 9999?', 100, '$2b$10$J/Gr62zjV1SnWTHIF4vkzOoNQYwpxbv6XLCt3vZILGLxlDGLqd7sG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3182c2fe-9724-459d-b6a1-3ccd1cec0275', '884ee166-21d8-4336-a519-6ccdf111068c', 'Chain Creator', 'Run: iptables -N MYCHAIN && iptables -L | grep MYCHAIN. What chain name appears?', 100, '$2b$10$lfwyBgwJekcj69Fv.wQnpONgSwYyGzc4rkm/9M6RIY.NHNGVnmTH.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6fab4c3f-70d8-46f4-8279-dff5ceb48142', '884ee166-21d8-4336-a519-6ccdf111068c', 'IP Blocker', 'Run: iptables -A INPUT -s 10.10.10.10 -j DROP && iptables -L INPUT -n | grep 10.10.10.10. What target?', 100, '$2b$10$XzAt61fJ2fdvXBfQvgqSXOrEsShQFQ8uNwUA473yJ4jOZh9l6vjhS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c15ea07f-b653-42d3-8e7f-15e6161a9289', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rate Limiter', 'Run: iptables -A INPUT -p tcp --dport 80 -m limit --limit 10/min --limit-burst 20 -j ACCEPT && iptables -L INPUT -n | grep "limit:10/min". Is limit shown? (yes/no)', 100, '$2b$10$GTFF6BTqb75vzZtuoL.ZuerDiw9RVE2JMRxs09Hld69dpmogJqS8u');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9c6e1770-7eea-43c4-b9de-d33b9be0eb9e', '884ee166-21d8-4336-a519-6ccdf111068c', 'State Inspector', 'Run: iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT && iptables -L INPUT -n | grep ESTABLISHED. What states are listed?', 100, '$2b$10$ZxL1jynyBuQSwHoaH6AUneTICfJnJX5QuGKVUJbiyB5Z0K.icZ5Em');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('47df89ff-a12f-4354-b039-38f3cd8e7b4a', '884ee166-21d8-4336-a519-6ccdf111068c', 'NAT Creator', 'Run: iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80 && iptables -t nat -L PREROUTING -n | grep 8080. What target?', 100, '$2b$10$J3WOXG0rpg23d1IETFrmE.zagIfGn.6kj3TkcZXESdv9rg2gNp93a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e48e4ce0-54e0-482c-a787-52978929a926', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Saver', 'Run: iptables-save > /tmp/iptables_rules.txt && wc -l /tmp/iptables_rules.txt. How many lines of rules?', 100, '$2b$10$cx3PXN8qHCD5i6.NvQZPbOXlFv9lub/mqGnhpqwyvzV2X3NhORPlu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('39cee1f0-3ef1-4924-a13c-d4eaf017d8fa', '884ee166-21d8-4336-a519-6ccdf111068c', 'Log Logger', 'Run: iptables -A INPUT -p tcp --dport 8080 -j LOG --log-prefix "FIREWALL: " && iptables -L INPUT -n | grep LOG. What log prefix is shown?', 100, '$2b$10$zvbnn5TBI.l2feLlQwJqnOk3dnEehrPvWS9AENyjFhPfFqbtqYZE6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('65744a4f-a72c-4e08-9144-b61e504cfc6b', '884ee166-21d8-4336-a519-6ccdf111068c', 'Interface Binder', 'Run: iptables -A INPUT -i eth0 -j ACCEPT && iptables -L INPUT -n | grep eth0. What interface is shown?', 100, '$2b$10$frUKaWrfedJYRGBE5eEaXeUxpmaSA8WR2q6Sfpsz7G1yBebrtQcJS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('19401434-280f-4a1f-8b50-77c500429688', '884ee166-21d8-4336-a519-6ccdf111068c', 'Packet Counter', 'Run: iptables -Z INPUT && iptables -L INPUT -v -n | head -3. What is the pkts count for INPUT chain?', 100, '$2b$10$YDrBVc1GfL9AMzQ4BB0woukTYFlLsTYShpr.7OzdidRmiXa397xfe');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8187a869-0d34-4242-b886-ee02b070fb4d', '884ee166-21d8-4336-a519-6ccdf111068c', 'Flush Master', 'Run: iptables -F MYCHAIN && iptables -L MYCHAIN -n | wc -l. How many rules in MYCHAIN after flush?', 75, '$2b$10$479Jw0KoyB.0IBMaFEhGUuqLlB3Mo/LP1IegqBlE23T3G9QWODaOS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4ef96924-4504-41c0-899d-9ff285e21fe3', '884ee166-21d8-4336-a519-6ccdf111068c', 'Cleanup', 'Run: iptables -F && iptables -X MYCHAIN 2>/dev/null; iptables -t nat -F PREROUTING 2>/dev/null; echo "firewall_done". What is the output?', 75, '$2b$10$ixieQ8a/b.EOJyY9DTDxouAg9EN0GgyLt707D88zwiIgIHYReV15u');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cc856341-beae-4026-b072-3e8989c0b0da', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Creator', 'Create zone file: /etc/bind/zones/aeroacademy.local. Add SOA record for aeroacademy.local. Run: named-checkzone aeroacademy.local /etc/bind/zones/aeroacademy.local 2>&1 | tail -1. What is the status?', 75, '$2b$10$WdZ3/iqdwruB1UmVGBK.JuzukH0pLbncXFcU7xTJYiTa6TvLGXr2y');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a65a230e-ee33-4440-9f80-2c37cae388dc', 'e0decd06-4a2e-4f94-965a-79854928514d', 'A Record', 'Add A record: aeroacademy.local IN A 192.168.1.100. Run: grep "IN A" /etc/bind/zones/aeroacademy.local. What IP is shown?', 75, '$2b$10$y6onEq/2YwGWc.KFCa8gWOp0kD7ylEWs1clX1gofXUQtHRIQnSte.');
