INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8559541d-f1e2-4ddb-be96-6b5a6280daea', '50d6a493-7898-473d-8287-137229593da9', 'Virtual Host Builder', 'Create /etc/nginx/sites-available/mysite.conf with a server block listening on port 9090, root /var/www/mysite. Create /var/www/mysite/index.html with "Hello Custom". Enable the site with ln -s and reload nginx. Run: curl -s localhost:9090. What is the content?', 100, '$2b$10$6N9pZIgcN0OY6kPj/EzPo.jgJIigKBor81DFsscxxfia2IYUJbcla');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c80e132a-6f9c-4a1f-ac9d-e06bd002e37f', '50d6a493-7898-473d-8287-137229593da9', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$Jb7bPz1LeOOdhlqdK9dgJerfNft1so4WUdfafy6UFiOnsRxzKszIC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('210feb7b-b9a9-47ed-8668-25f29afd1eb2', '50d6a493-7898-473d-8287-137229593da9', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$4hU.U3xQO1SdvXIlT9AaGetp7onOznFqWoKvhAz1HIHS54tAcYqS2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0dfebcb0-11c4-4ce4-897e-a5aca3806592', '50d6a493-7898-473d-8287-137229593da9', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$OwRQsLeZRuhNAvl8/lFdpOOPw.otS7kO/sypmm2wbLEg5PrJLlkTm');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d247bf48-e6bb-4f9a-a2bc-0f124b787bcf', '50d6a493-7898-473d-8287-137229593da9', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$Q0HikcLbUEa9PZFt2LqDn.Mh05DWiq4Rr3hilcSbQ1vkEgv1arIqi');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('43305fee-9b90-4d43-9f04-c8d79059da2e', '50d6a493-7898-473d-8287-137229593da9', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$elkB2IiKkel0XCZPH7telOJT.HT2Li8UEbx5fuo2wfDk9/3tehI7W');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c2ccbd05-bda5-4f42-adea-3bc0e8226bb0', '50d6a493-7898-473d-8287-137229593da9', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$FpYmNrjNypBu.WAywKOgnOZEDgxNo/eo2VrT0qpqHucnAsGdYDZUa');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dc2e76e2-58a3-4698-aa5f-20f028e991f4', '50d6a493-7898-473d-8287-137229593da9', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$m2ObR65FpuFg.0VrTGxhGeq5UQbWlxzEt52x9VgMGj5zV9gx2I76O');
